#[capability(
    module = "pipedrive",
    id = "update-deal",
    display_name = "Update a deal",
    description = r##"Updates the properties of a deal."##,
    side_effects = true
)]
pub async fn update_deal(input: UpdateDealInput) -> Result<UpsertDealResponse, AgentError> {
    let connection = kit::require_connection(&input._connection, "PIPEDRIVE")?;
    let path = format!("/api/v2/deals/{id}", id = kit::encode_path(&input.id));
    kit::Request::new("PATCH", path)
        .json_body(
            kit::Body::new()
                .field_opt("archive_time", &input.archive_time)
                .field_opt("close_time", &input.close_time)
                .field_opt("currency", &input.currency)
                .field_opt("custom_fields", &input.custom_fields)
                .field_opt("expected_close_date", &input.expected_close_date)
                .field_opt("is_archived", &input.is_archived)
                .field_opt("is_deleted", &input.is_deleted)
                .field_opt("label_ids", &input.label_ids)
                .field_opt("lost_reason", &input.lost_reason)
                .field_opt("lost_time", &input.lost_time)
                .field_opt("org_id", &input.org_id)
                .field_opt("owner_id", &input.owner_id)
                .field_opt("person_id", &input.person_id)
                .field_opt("pipeline_id", &input.pipeline_id)
                .field_opt("probability", &input.probability)
                .field_opt("stage_id", &input.stage_id)
                .field_opt("status", &input.status)
                .field_opt("title", &input.title)
                .field_opt("value", &input.value)
                .field_opt("visible_to", &input.visible_to)
                .field_opt("won_time", &input.won_time),
            "PIPEDRIVE",
        )?
        .send(connection, "PIPEDRIVE")
        .await
}

